 [('领取与隔离执行权','claim 使用数据库锁与全局活跃租约计数限并发；checkpoint 必须持有当前未过期 token，取消或接管会隔离旧执行器。'),('按检查点继续','模型请求已保存后再执行工具；恢复只重放尚无结果的只读调用。预算随任务保存，硬崩溃后的墙钟时间也计入。'),('显式恢复或取消','POST /resume 重启原任务执行，waiting_approval 不能被绕过；POST /cancel 转换终态并释放执行权。没有后台自动扫描积压队列。'),('补发持久化事件','GET /events 用 after 或 Last-Event-ID 过滤已保存事件。断开事件流不取消任务；重新订阅不创建新任务。')],
 [('queued 是 phase','刚创建时 status=running、phase=queued；不能把 queued 当成新增 status 枚举。完成、失败、取消才是终态。'),('SSE 不是真实词元流','text_delta 在完整答案校验后按 120 字符切片，TTFT 未测。恢复可能再次调用模型或只读工具，不保证无重复计费。')],
